DECLARE c1 CURSOR FOR SELECT 1 as c UNION SELECT 2 as c;
BEGIN
    LET a ARRAY := [];
    FOR rec IN c1 DO
        a := array_append(a, rec.c);
    END FOR;
    RETURN a;
END;

DECLARE c1 CURSOR FOR SELECT 1 as c;
BEGIN
    LET o OBJECT := {};
    FOR rec IN c1 DO
        o := object_insert(o, 'k', rec.c);
    END FOR;
    RETURN o;
END;

